import { useEffect, useState } from "react";

function Clock({ city }) {
  const [time, setTime] = useState(new Date().toLocaleTimeString());

  useEffect(() => {
    const id = setInterval(() => {
      setTime(new Date().toLocaleTimeString());
    }, 1000);

    // Without this return the interval keeps running after unmount
    return () => clearInterval(id);
  }, [city]); // a new city re-runs the effect and cleans the old timer first

  return <p>{city}: {time}</p>;
}

import { useReducer } from "react";

const initial = { adults: 2, children: 0, breakfast: false };

function reducer(state, action) {
  switch (action.type) {
    case "adults":
      // Never go below one adult
      return { ...state, adults: Math.max(1, state.adults + action.delta) };
    case "children":
      return { ...state, children: Math.max(0, state.children + action.delta) };
    case "breakfast":
      return { ...state, breakfast: action.value };
    case "reset":
      return initial;
    default:
      throw new Error("Unknown action: " + action.type);
  }
}

export default function BookingForm() {
  const [state, dispatch] = useReducer(reducer, initial);

  return (
    <form>
      <p>Adults: {state.adults}</p>
      <button type="button" onClick={() => dispatch({ type: "adults", delta: 1 })}>
        Add adult
      </button>
      <button type="button" onClick={() => dispatch({ type: "reset" })}>
        Reset
      </button>
    </form>
  );
}

import { useMemo, useState } from "react";

function HotelTable({ hotels }) {
  const [query, setQuery] = useState("");

  // Filtering runs only when hotels or query change, not on every keystroke elsewhere
  const visible = useMemo(() => {
    const needle = query.trim().toLowerCase();
    return hotels.filter((hotel) => hotel.name.toLowerCase().includes(needle));
  }, [hotels, query]);

  const totalStars = useMemo(
    () => visible.reduce((sum, hotel) => sum + hotel.stars, 0),
    [visible]
  );

  return (
    <div>
      <input value={query} onChange={(event) => setQuery(event.target.value)} />
      <p>{visible.length} hotels, {totalStars} stars</p>
    </div>
  );
}

import { memo, useCallback, useState } from "react";

// memo skips the render only when props are equal by reference
const Row = memo(function Row({ hotel, onSelect }) {
  return <button onClick={() => onSelect(hotel.hotel_id)}>{hotel.name}</button>;
});

export default function HotelList({ hotels }) {
  const [selected, setSelected] = useState(null);

  // A new function each render would defeat memo on every Row
  const handleSelect = useCallback((hotelId) => {
    setSelected(hotelId);
  }, []); // setState is stable, so no dependency is needed

  return (
    <div>
      <p>Selected: {selected}</p>
      {hotels.map((hotel) => (
        <Row key={hotel.hotel_id} hotel={hotel} onSelect={handleSelect} />
      ))}
    </div>
  );
}

import { createContext, useContext, useState } from "react";

const ThemeContext = createContext("light");

function Toolbar() {
  // Any component below the provider can read the theme
  const theme = useContext(ThemeContext);
  return <button className={theme}>Save</button>;
}

