import { useState, useTransition } from "react";

function HotelSearch({ hotels }) {
  const [query, setQuery] = useState("");
  const [list, setList] = useState(hotels);
  const [isPending, startTransition] = useTransition();

  function handleChange(event) {
    const next = event.target.value;
    setQuery(next); // urgent, must follow the keystroke

    startTransition(() => {
      // Non urgent, React may interrupt this render
      setList(hotels.filter((hotel) => hotel.name.includes(next)));
    });
  }

  return (
    <div>
      <input value={query} onChange={handleChange} />
      {isPending && <p>Filtering...</p>}
      <ul>{list.map((hotel) => <li key={hotel.hotel_id}>{hotel.name}</li>)}</ul>
    </div>
  );
}

import { useDeferredValue, useState } from "react";

function SlowList({ text }) {
  // Imagine a thousand rows here
  return <p>Rendering {text}</p>;
}

export default function Search() {
  const [query, setQuery] = useState("");
  const deferredQuery = useDeferredValue(query);

  // The input updates immediately, the list follows when React is free
  const stale = query !== deferredQuery;

  return (
    <div>
      <input value={query} onChange={(event) => setQuery(event.target.value)} />
      <div style={{ opacity: stale ? 0.5 : 1 }}>
        <SlowList text={deferredQuery} />
      </div>
    </div>
  );
}

import { useLayoutEffect, useRef, useState } from "react";

function Tooltip({ children }) {
  const boxRef = useRef(null);
  const [height, setHeight] = useState(0);

  useLayoutEffect(() => {
    // Measuring here avoids a visible jump after paint
    setHeight(boxRef.current.getBoundingClientRect().height);
  }, [children]);

  return (
    <div>
      <div ref={boxRef}>{children}</div>
      <p>Tooltip height: {height}px</p>
    </div>
  );
}

