import { useState } from "react";
import { createPortal } from "react-dom";

function Modal({ open, onClose, children }) {
  if (!open) return null;

  // The markup lands in body, outside the parent stacking context
  return createPortal(
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal" onClick={(event) => event.stopPropagation()}>
        {children}
      </div>
    </div>,
    document.body
  );
}

export default function App() {
  const [open, setOpen] = useState(false);
  return (
    <>
      <button onClick={() => setOpen(true)}>Book</button>
      <Modal open={open} onClose={() => setOpen(false)}>Booking form</Modal>
    </>
  );
}

import { Component } from "react";

class ErrorBoundary extends Component {
  state = { error: null };

  // Called during render, so it only updates state
  static getDerivedStateFromError(error) {
    return { error };
  }

  // Side effects such as logging belong here
  componentDidCatch(error, info) {
    console.error("Hotel page failed", error, info.componentStack);
  }

  render() {
    if (this.state.error) {
      return (
        <div>
          <p>Something failed.</p>
          <button onClick={() => this.setState({ error: null })}>Retry</button>
        </div>
      );
    }
    return this.props.children;
  }
}

export default ErrorBoundary;

import { useEffect, useState } from "react";

function useFetch(url) {
  const [data, setData] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const controller = new AbortController();
    setLoading(true);

    fetch(url, { signal: controller.signal })
      .then((response) => {
        if (!response.ok) throw new Error("HTTP " + response.status);
        return response.json();
      })
      .then(setData)
      .catch((caught) => {
        if (caught.name !== "AbortError") setError(caught);
      })
      .finally(() => setLoading(false));

    // Cleanup aborts the request when url changes or the component unmounts
    return () => controller.abort();
  }, [url]);

  return { data, error, loading };
}

export default function HotelList() {
  const { data, error, loading } = useFetch("/api/hotels");

  if (loading) return <p>Loading...</p>;
  if (error) return <p>{error.message}</p>;
  return <ul>{data.map((hotel) => <li key={hotel.hotel_id}>{hotel.name}</li>)}</ul>;
}

import { createContext, useContext, useMemo, useState } from "react";

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null);

  // The value object is memoized so consumers skip needless renders
  const value = useMemo(() => ({ user, login: setUser, logout: () => setUser(null) }), [user]);

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used inside AuthProvider");
  }
  return context;
}

